/**
 * Schema Normalizer — Bidirectional camelCase ↔ snake_case Bridge
 * 
 * The MCP tool definitions (mcp-tool-definitions.json) use camelCase parameters
 * while the Zod schemas in gravito-mcp-server.ts use snake_case.
 * 
 * This module normalizes incoming parameters to match the target schema,
 * preventing validation failures at the naming boundary.
 * 
 * Strategy:
 * 1. Build a mapping from each tool's Zod schema field names
 * 2. On incoming request, detect if params are camelCase or snake_case
 * 3. Convert to match the Zod schema's expected naming convention
 * 4. Preserve unknown fields (pass-through for extensibility)
 * 
 * This is a pure function transform — no side effects, no state.
 */

import { GRAVITO_TOOLS } from '../agent/mcp/gravito-mcp-server';

// ============================================================================
// CONVERSION UTILITIES
// ============================================================================

/**
 * Convert camelCase to snake_case
 * e.g., "surfaceType" → "surface_type", "artifactType" → "artifact_type"
 */
export function camelToSnake(str: string): string {
  return str.replace(/([A-Z])/g, '_$1').toLowerCase();
}

/**
 * Convert snake_case to camelCase
 * e.g., "surface_type" → "surfaceType", "artifact_type" → "artifactType"
 */
export function snakeToCamel(str: string): string {
  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

// ============================================================================
// SCHEMA FIELD MAP
// ============================================================================

interface ToolFieldMap {
  /** Fields defined in the Zod schema (authoritative names) */
  schemaFields: Set<string>;
  /** Map from camelCase alias → snake_case schema field */
  camelToSchemaMap: Map<string, string>;
  /** Map from snake_case alias → camelCase schema field (for JSON-def tools) */
  snakeToSchemaMap: Map<string, string>;
}

const fieldMapCache = new Map<string, ToolFieldMap>();

function buildFieldMapCache(): void {
  if (fieldMapCache.size > 0) return;

  for (const tool of GRAVITO_TOOLS) {
    const shortName = tool.name.replace('gravito.', '');
    const inputSchema = tool.inputSchema as unknown;

    if (!inputSchema || !inputSchema._def) {
      // Not a Zod schema — skip
      continue;
    }

    // Extract field names from Zod schema shape
    let shape: Record<string, unknown> = {};
    try {
      if (inputSchema.shape) {
        shape = inputSchema.shape;
      } else if (inputSchema._def?.shape) {
        shape = typeof inputSchema._def.shape === 'function' 
          ? inputSchema._def.shape() 
          : inputSchema._def.shape;
      }
    } catch {
      continue;
    }

    const schemaFields = new Set(Object.keys(shape));
    const camelToSchemaMap = new Map<string, string>();
    const snakeToSchemaMap = new Map<string, string>();

    for (const field of schemaFields) {
      // If field is snake_case, create camelCase alias
      if (field.includes('_')) {
        const camelAlias = snakeToCamel(field);
        if (camelAlias !== field) {
          camelToSchemaMap.set(camelAlias, field);
        }
      }
      // If field is camelCase, create snake_case alias
      if (/[A-Z]/.test(field)) {
        const snakeAlias = camelToSnake(field);
        if (snakeAlias !== field) {
          snakeToSchemaMap.set(snakeAlias, field);
        }
      }
    }

    fieldMapCache.set(shortName, { schemaFields, camelToSchemaMap, snakeToSchemaMap });
  }
}

// ============================================================================
// NORMALIZER
// ============================================================================

/**
 * Normalize tool arguments to match the Zod schema's field naming convention.
 * 
 * For a tool with snake_case schema (e.g., surface_type):
 *   - Input { surfaceType: "medical" } → { surface_type: "medical" }
 * 
 * For a tool with camelCase schema (e.g., artifactId):
 *   - Input { artifact_id: "abc" } → { artifactId: "abc" }
 * 
 * Unknown fields are passed through unchanged.
 */
export function normalizeSchemaParams(
  toolName: string,
  args: Record<string, unknown>
): Record<string, unknown> {
  buildFieldMapCache();

  const shortName = toolName.replace('gravito.', '');
  const fieldMap = fieldMapCache.get(shortName);

  if (!fieldMap) {
    // No schema mapping available — return as-is
    return args;
  }

  const normalized: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(args)) {
    // 1. If key exactly matches a schema field, use it directly
    if (fieldMap.schemaFields.has(key)) {
      normalized[key] = value;
      continue;
    }

    // 2. If key is camelCase and maps to a snake_case schema field
    if (fieldMap.camelToSchemaMap.has(key)) {
      const schemaKey = fieldMap.camelToSchemaMap.get(key)!;
      // Don't overwrite if the schema key was already provided
      if (!(schemaKey in normalized)) {
        normalized[schemaKey] = value;
      }
      continue;
    }

    // 3. If key is snake_case and maps to a camelCase schema field
    if (fieldMap.snakeToSchemaMap.has(key)) {
      const schemaKey = fieldMap.snakeToSchemaMap.get(key)!;
      if (!(schemaKey in normalized)) {
        normalized[schemaKey] = value;
      }
      continue;
    }

    // 4. Unknown field — pass through (extensibility)
    normalized[key] = value;
  }

  return normalized;
}

/**
 * Get normalization stats for diagnostics
 */
export function getSchemaNormalizerStats(): {
  toolsWithMapping: number;
  totalCamelAliases: number;
  totalSnakeAliases: number;
  toolNames: string[];
} {
  buildFieldMapCache();

  let totalCamelAliases = 0;
  let totalSnakeAliases = 0;

  for (const [, map] of fieldMapCache) {
    totalCamelAliases += map.camelToSchemaMap.size;
    totalSnakeAliases += map.snakeToSchemaMap.size;
  }

  return {
    toolsWithMapping: fieldMapCache.size,
    totalCamelAliases,
    totalSnakeAliases,
    toolNames: Array.from(fieldMapCache.keys()),
  };
}

/**
 * Check if a tool has schema normalization available
 */
export function hasSchemaMapping(toolName: string): boolean {
  buildFieldMapCache();
  const shortName = toolName.replace('gravito.', '');
  return fieldMapCache.has(shortName);
}

